INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('425d8a5f-a940-4f2a-8528-af19d1f28e3f', 'Education & Training', 'Our comprehensive training programs combine classroom education with real-world scenarios at mock jobsites. Learn best practices, understand utility marking standards, and master the 811 process.', 'training.html', '🎓', 0);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('505c9edc-365c-4b55-a5d0-bc58a7295914', 'Utility Locate Rodeo', 'The Utility Locate Rodeo is an annual competition that showcases the locating profession and encourages best practices among utility locators. This event recognizes excellence and promotes safety.', 'utility-locate-rodeo.html', '🏆', 1);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('f77f4ece-44ec-4d38-8869-e09edf621853', 'Silver Shovel Awards', 'The Silver Shovel Awards recognize excavators and contractors who demonstrate strong safety ethics and consistent best practices in damage prevention. Celebrate excellence in our industry.', 'silver-shovel-award.html', '⭐', 2);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('561a4c9f-ebf4-4cd4-a1e7-1e344fd820a3', '811 Day (August 11)', '811 Day is an annual public awareness campaign held on August 11th (8/11) to promote the importance of calling 811 before digging. This nationwide initiative helps prevent utility damage.', '811-day.html', '📅', 3);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('563f7423-f227-4fd3-b3d6-96de3b369966', 'Golf Tournament Fundraiser', 'The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun.', 'golf-tournament.html', '⛳', 4);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('808245f9-3813-4f5e-a964-e4ef3204bc4c', 'Craig Rogers Award', 'The Craig Rogers Award honors excellence in damage prevention in memory of our dear friend and colleague. This award celebrates leaders who demonstrate outstanding commitment to safety.', 'craig-rogers-award.html', '🎖️', 5);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('c4222a63-84bf-4a35-9995-21c548af2368', 'Operations', 'The Operations working group plays a critical role in ensuring the effective operation of Nevada''s One Call Center system. This group brings together stakeholders to discuss operational improvements.', 'operations.html', '⚙️', 6);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('8fc59f23-d5fb-4652-8501-cd8d2124b362', 'Embedded Facilities Taskforce', 'The Embedded Facilities Taskforce is a technical working group focused on addressing the unique challenges associated with embedded facilities and infrastructure.', 'embedded-facilities-taskforce.html', '⛏', 7);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('71a72142-21bd-4bd4-b54d-177c31dc5d73', 'Budget Committee', 'The Budget Committee oversees NRCGA''s financial planning, budget development, and fiscal responsibility to ensure the organization''s long-term sustainability.', 'budget-committee.html', '💰', 8);
INSERT OR REPLACE INTO programs (id, title, description, link, icon, sort_order)
     VALUES ('e1baf69a-b632-46ae-9366-353e8d5b80ab', 'Technical Solutions Committee', 'The Technical Solutions Committee evaluates and develops innovative technologies and methods to improve damage prevention practices across Nevada.', 'technical-solutions-committee.html', '🔧', 9);
