INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-001', 'What is 811?', '811 is the national "Call Before You Dig" number that connects you to your local one-call center. When you call 811, you''ll be connected to operators who will notify utility companies about your planned excavation. Those utilities will then send locators to mark the approximate location of underground lines at no cost to you.', 0, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-002', 'How far in advance should I call 811?', 'You should call 811 at least 2-3 business days before you plan to start digging. This gives utility operators enough time to mark underground lines. Some states require specific notice periods, so check your local requirements.', 1, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-003', 'Is calling 811 free?', 'Yes, calling 811 is completely free. There is no charge for the service, and utility operators mark underground lines at no cost to you.', 2, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-004', 'What information do I need when calling 811?', 'When calling 811, be ready to provide:

- The exact location where you''ll be digging (address or description)
- Type of work you''re planning (fence, landscaping, construction, etc.)
- When you plan to start digging
- Your contact information', 3, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-005', 'What do the colored flags and paint marks mean?', 'Utility locators use standardized colors to mark different types of underground utilities:

- **Red:** Electric power lines
- **Yellow:** Gas, oil, or petroleum lines
- **Orange:** Communication lines (phone, cable, internet)
- **Blue:** Potable water
- **Green:** Sewers and drain lines
- **Purple:** Reclaimed water or irrigation
- **White:** Proposed excavation limits
- **Pink:** Temporary survey markings', 4, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-006', 'How accurate are the utility marks?', 'Utility marks indicate the approximate location of underground lines. They are not exact, so you should use hand tools or vacuum excavation within 18-24 inches of marked utilities. Always dig carefully and watch for any unmarked utilities that may have been missed.', 5, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-007', 'How long are the marks valid?', 'Mark validity periods vary by state and utility type, but typically range from 10 to 30 days. If marks become damaged, unclear, or if your project extends beyond the validity period, you should call 811 again to request remarking.', 6, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-008', 'What if I hit a utility line?', 'If you hit a utility line:

1. Stop digging immediately
2. Evacuate the area if there''s any danger (gas leak, electrical hazard)
3. Call 911 if there''s an emergency
4. Contact the utility company
5. Report the damage to your local one-call center', 7, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-009', 'Do I need to call 811 for small projects like planting flowers?', 'Yes, you should call 811 for any digging project, no matter how small. Even shallow digging can damage utility lines. It''s always better to be safe and have utilities marked before you dig.', 8, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-010', 'What if I''m only digging a few inches deep?', 'Many utility lines are buried just a few inches below the surface. Even shallow digging can damage these lines. Always call 811 before digging, regardless of depth.', 9, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-011', 'Can I use power tools near marked utilities?', 'You should use hand tools or vacuum excavation within 18-24 inches of marked utilities. Power tools can easily damage underground lines, even when you think you''re being careful.', 10, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-012', 'What if no utilities are marked?', 'If no utilities are marked, it doesn''t necessarily mean there are no underground lines. Some utilities may not be members of the one-call system, or lines may have been installed without proper documentation. Always dig carefully and watch for any signs of underground utilities.', 11, 1);
INSERT OR REPLACE INTO qa_items (id, question, answer_md, sort_order, published)
       VALUES ('qa-013', 'Is calling 811 required by law?', 'Yes, in most states, calling 811 before digging is required by law. Failure to call can result in fines, liability for damages, and criminal penalties in some cases. Even if it''s not legally required in your area, it''s always the safe and responsible thing to do.', 12, 1);
