INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000b537f6f5', 'budget-committee', 'Budget Committee', 'NRCGA Programs', 'The Budget Committee oversees NRCGA''s financial planning, budget development, and fiscal responsibility to ensure the organization''s long-term sustainability.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Budget Committee plays a critical role in NRCGA''s financial management and strategic planning. This committee is responsible for developing annual budgets, monitoring financial performance, and ensuring the organization''s resources are allocated effectively to support our mission and programs.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Key Responsibilities","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Develop and review annual operating budgets\n• ✓ Monitor financial performance and expenditures\n• ✓ Provide financial oversight and recommendations to the Board\n• ✓ Ensure fiscal responsibility and transparency","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000e8c2e4a7', '811-day', '811 Day (August 11)', 'NRCGA Programs', 'Public awareness outreach to spread "Call 811 Before You Dig" across Nevada communities.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/811Day2024b.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Join us at the Ball park!","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"image","url":"assets/images/programs/811 day/811day26flyer.png","alt":"A day at the ball park!","caption":"","width":"full","align":"left"},{"type":"cta_button","label":"Get Your Tickets!","url":"zero-at-fault-damages.html","style":{"align":"left"}},{"type":"text","body":"Every year on August 11 (8/11), NRCGA joins the national effort to raise awareness about the importance of calling 811 before digging. This annual event brings together stakeholders from across Nevada''s damage prevention community to spread the message of safe digging practices.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This year the NRCGA is celebrating 811 Day with a night at the ballpark. Join us at the Aviators Stadium for good company, great baseball, and a shared commitment to safe digging. Tickets are just $8.11, fitting for the occasion!","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Why 811 Day Matters","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Raises public awareness about the importance of calling 811 before any digging project\n• ✓ Prevents utility damages that can cause injuries, service disruptions, and costly repairs\n• ✓ Builds a culture of safety across Nevada communities\n• ✓ Brings together stakeholders to celebrate damage prevention achievements","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"How We Celebrate","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"NRCGA organizes various activities and events throughout Nevada to mark 811 Day, including:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Community Events","body":"Public outreach events at community centers, parks, and public spaces"},{"icon":"✓","title":"Educational Workshops","body":"Training sessions for homeowners, contractors, and excavators"},{"icon":"✓","title":"Media Campaigns","body":"Social media and traditional media outreach to reach wider audiences"},{"icon":"✓","title":"Partnership Activities","body":"Collaborations with utilities, contractors, and community organizations"}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/LVBallpark811Day2024.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"image","url":"assets/images/programs/811 day/1722879392324-e1723053578491.jpg","alt":"811 Day Event 2024","caption":"","width":"lg","align":"left"}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-00002d73d4e9', 'craig-rogers-award', 'Craig Rogers Award', 'NRCGA Programs', 'Honoring Excellence in Damage Prevention in memory of our dear friend & colleague', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"grid","columns":3,"gap":"md","items":[{"icon":"✓","title":"","body":"\"I just want to do what is right.\""}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Why This Award Exists","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Craig Rogers Award celebrates leaders who:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":4,"gap":"md","items":[{"icon":"🛡️","title":"","body":"Demonstrate exceptional dedication"},{"icon":"🔨","title":"","body":"Deliver tangible improvements"},{"icon":"📖","title":"","body":"Share knowledge generously"},{"icon":"🤝","title":"","body":"Uphold integrity and character"}]},{"type":"text","body":"This recognition is not only about past achievements—it sets the standard for the future of damage prevention in Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Hall of Heroes","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"heading","level":3,"text":"Kristen Garcia","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Winner of the 2026!.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"image","url":"assets/images/programs/craig rogers/kristenwon.jpg","alt":"The Rogers Cup","caption":"","width":"full","align":"left"},{"type":"heading","level":3,"text":"The First of Many","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Kristen Garcia has made history as the first-ever recipient of the Craig Rogers Award. This honor recognizes an individual whose dedication to damage prevention and the 811 community reflects the very values Craig Rogers stood for. Kristen, we are so proud to celebrate you.","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Who Was Craig Rogers?","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"image","url":"assets/images/programs/craig rogers/CraigInField.png","alt":"Craig Rogers in the field","caption":"","width":"full","align":"left"},{"type":"text","body":"Video courtesy of USA North 811. https://www.youtube.com/@usanorth811","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Craig Rogers exemplified the best of Nevada''s damage prevention community—integrity, mentorship, and a relentless focus on doing the right thing. He built bridges across stakeholders and raised the bar for safety culture. This award honors professionals who continue that legacy and inspire others to follow.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"\"When we get there, we are going to look at the entire piece. What are you doing as an excavator? What are you doing as a utility operator? And trying to figure out how we can make things better.\"","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"— Craig Rogers","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Nominate a Champion","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Know someone who exemplifies Craig Rogers'' legacy? Nominate them for the Craig Rogers Award.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Submit a Nomination","url":"contact.html","style":{"align":"left"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-00004c1008da', 'training', 'Hands-On Learning for Safer Excavation', 'Safety Training', 'Comprehensive training programs combining classroom education with real-world scenarios at mock jobsites.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/education/OutsideTraining.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"Our comprehensive training programs combine classroom education with real-world scenarios at mock jobsites. Learn best practices, understand utility marking standards, and develop the skills needed for safe excavation.","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"What You''ll Learn","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Our training covers essential topics for safe excavation and damage prevention.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"🎯","title":"Utility Marking Standards","body":"Understand color codes, marking standards, and how to interpret utility locator marks."},{"icon":"🛠️","title":"Safe Excavation Practices","body":"Learn proper hand-digging techniques and safe distances from marked utilities."},{"icon":"📞","title":"811 Process","body":"Master the call-before-you-dig process and ticket management."},{"icon":"⚠️","title":"Damage Prevention","body":"Identify potential hazards and prevent damage to underground infrastructure."},{"icon":"📋","title":"Best Practices","body":"Industry standards and proven methods for safe excavation operations."},{"icon":"🤝","title":"Communication","body":"Effective communication with utility operators and locators."}]}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000b7569434', 'golf-tournament', 'Golf Tournament Fundraiser', 'NRCGA Programs', 'Proceeds support outreach, education, and damage prevention programs statewide.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/golf/NRCGAGolf.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The NRCGA Golf Tournament is an annual fundraising event that brings together members of Nevada''s damage prevention community for a day of golf, networking, and fun. Proceeds from the tournament directly support NRCGA''s outreach, education, and damage prevention programs across the state.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"How Your Support Helps","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Funds safety training programs for excavators and locators\n• ✓ Supports community outreach and public awareness campaigns\n• ✓ Enables recognition programs like the Silver Shovel Awards\n• ✓ Helps organize events like 811 Day and the Utility Locate Rodeo","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Tournament Details","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The NRCGA Golf Tournament typically includes:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"18-Hole Tournament","body":"Scramble format with prizes for top teams"},{"icon":"✓","title":"Networking Opportunities","body":"Connect with industry professionals and stakeholders"},{"icon":"✓","title":"Sponsorship Packages","body":"Multiple sponsorship levels available for businesses"},{"icon":"✓","title":"Awards & Recognition","body":"Prizes, raffles, and recognition for participants"}]}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-000059599137', 'utility-locate-rodeo', 'Utility Locate Rodeo', 'NRCGA Programs', 'Competition that showcases the locating profession and encourages best practices among utility locators', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/StcHYFS3_1000x667.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":3,"text":"About the Competition","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is an annual competition that brings together utility locators from across Nevada to demonstrate their skills, share knowledge, and celebrate excellence in damage prevention.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Participants compete in various challenges that test their expertise in identifying and marking underground utilities, their knowledge of best practices, and their accuracy. This event not only recognizes outstanding performance but also serves as an educational opportunity for the entire damage prevention community.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Event Highlights","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"✓","title":"Skills Competition","body":"Locators demonstrate their expertise in identifying and marking underground utilities accurately and efficiently."},{"icon":"✓","title":"Best Practices Showcase","body":"Participants share knowledge and techniques that promote safety and accuracy in utility locating."},{"icon":"✓","title":"Networking & Education","body":"Connect with peers, learn from industry experts, and stay updated on the latest technologies and techniques."},{"icon":"✓","title":"Recognition & Awards","body":"Outstanding performers are recognized for their excellence in utility locating and damage prevention."}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/wJysU-NA.jpg","alt":"","caption":"","width":"full","align":"center"}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is organized by the NRCGA''s Utility Locate Rodeo Committee. Whether you''re interested in participating as a competitor, volunteering, or sponsoring the event, we''d love to have you involved.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Participate","body":"Register as a competitor and showcase your locating skills."},{"icon":"✓","title":"Volunteer","body":"Help organize and run the event as a volunteer."},{"icon":"✓","title":"Sponsor","body":"Support the event as a sponsor."}]}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/locate rodeo/NRCGA-Utility_Locate_Rodeo-Logo.png","alt":"NRCGA Utility Locate Rodeo Logo","caption":"","width":"full","align":"left"},{"type":"heading","level":2,"text":"Utility Locate Rodeo Committee","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Utility Locate Rodeo is planned and executed by dedicated volunteers from the NRCGA''s Utility Locate Rodeo Committee. This committee works year-round to organize the annual competition, coordinate logistics, and ensure a successful event that benefits the entire damage prevention community.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"If you''re interested in joining the committee or learning more about how the rodeo is organized, please contact us.","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000003fd7ec', 'operations', 'Operations', 'NRCGA Programs', 'This group oversees how the One Call Center operates for Nevada and discusses potential changes that could impact its functionality.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Operations working group plays a critical role in ensuring the effective operation of Nevada''s One Call Center system. This group brings together stakeholders to discuss operational improvements, address challenges, and ensure that the 811 system serves Nevada''s damage prevention community effectively.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Committee Responsibilities","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Operations working group is made up of dedicated volunteers from across Nevada''s damage prevention community. Members meet regularly to:","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":2,"gap":"md","items":[{"icon":"✓","title":"Review Operations","body":"Monitor One Call Center performance and identify areas for improvement"},{"icon":"✓","title":"Evaluate Changes","body":"Assess proposed changes and their potential impact on system functionality"},{"icon":"✓","title":"Problem Solving","body":"Address operational challenges and develop solutions"},{"icon":"✓","title":"Stakeholder Coordination","body":"Work with utilities, excavators, and other stakeholders on operational matters"}]}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000ce0bcf73', 'silver-shovel-award', 'Silver Shovel Award', 'NRCGA Programs', 'Celebrating Excavators & the Prevention of Damage to Underground Utilities', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"The Best of The Best","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"image","url":"assets/images/programs/silver shovel/jbmjumbo.jpg","alt":"Silver Shovel Award","caption":"","width":"lg","align":"left"},{"type":"image","url":"assets/images/programs/silver shovel/shovelhandoff.jpg","alt":"2026 Silver Shovel Award Winner - JBM Underground","caption":"","width":"md","align":"left"},{"type":"heading","level":3,"text":"Congratulations, JBM Underground!","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"2026 Silver Shovel Award Winner!","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Award Celebration: April 18, 2026 at Lees Family Forum, Las Vegas","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Silver Shovel Hall of Fame","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"grid","columns":4,"gap":"md","items":[{"icon":"✓","title":"","body":"C&S Company2025"},{"icon":"✓","title":"","body":"Southwest Gas2024"},{"icon":"✓","title":"","body":"Las Vegas Paving2023"},{"icon":"✓","title":"","body":"Lone Mountain Excavation2021"},{"icon":"✓","title":"","body":"Tab Contractors2018"},{"icon":"✓","title":"","body":"Future Infrastructure Services2019"},{"icon":"✓","title":"","body":"Silver Lake Construction2017"},{"icon":"✓","title":"","body":"Byrd Underground2016"}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"2026 Zero At-Fault Damages List","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"The Silver Shovel Award is part of NRCGA''s broader recognition efforts. We also celebrate excavators who achieve zero at-fault damages and build a safety-first culture.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"View All Excavators who had Zero At-Fault Damages!","url":"zero-at-fault-damages.html","style":{"align":"left"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000cdf3811a', 'technical-solutions-committee', 'Technical Solutions Committee', 'NRCGA Programs', 'The Technical Solutions Committee evaluates and develops innovative technologies and methods to improve damage prevention practices across Nevada.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Technical Solutions Committee focuses on identifying, evaluating, and promoting innovative technologies and methodologies that enhance damage prevention efforts. This committee brings together technical experts to explore solutions that improve locating accuracy, excavation safety, and overall system effectiveness.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This committee is also the primary steward of the NRCGA website.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Key Responsibilities","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• ✓ Evaluate new technologies for damage prevention applications\n• ✓ Develop technical standards and best practices\n• ✓ Research and test innovative locating and excavation methods\n• ✓ Provide technical guidance to the NRCGA community","style":{"align":"left","textSize":"md","textColor":"default"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-000008417f9d', 'embedded-facilities-taskforce', 'Embedded Facilities Taskforce', 'NRCGA Programs', 'Addresses challenges and solutions related to embedded facilities and infrastructure. This working group focuses on technical solutions for damage prevention.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"text","body":"The Embedded Facilities Taskforce is a technical working group focused on addressing the unique challenges associated with embedded facilities and infrastructure. This group brings together experts from across Nevada''s damage prevention community to develop solutions and best practices for working with embedded utilities.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"This committee is collecting occurrences of embedded underground facilities. If you''ve discovered an embedded facility, please use the form linked below.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Discovered an Embedded Facility?","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to submit your discovery of an embedded facility.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Submit Occurrence","url":"https://forms.gle/eitenb2XvR5xChUU6","style":{"align":"left"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Get Involved","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Click here to view your committee enrollment.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Committee Enrollment","url":"committee-enrollment.html","style":{"align":"left"}},{"type":"text","body":"Interested in participating in this program?","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Contact Us","url":"contact.html","style":{"align":"left"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-0000b013e218', 'about-811', 'What is 811?', 'Call Before You Dig', '811 is the national "Call Before You Dig" number that connects you to your local one-call center to mark underground utilities.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"image","url":"assets/images/programs/icons/811 icon.svg","alt":"811 Call Before You Dig","caption":"","width":"full","align":"left"},{"type":"heading","level":3,"text":"Why It Matters","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Hitting an underground utility line can cause serious injury, service disruptions, and costly repairs. A simple call to 811 ensures utilities are marked, keeping you and your community safe.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Whether you''re planting a tree, installing a fence, or starting a major construction project, calling 811 before you dig is the law in most states and is always the safe choice.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"columns","cols":2,"gap":"md","columns":[[{"type":"heading","level":2,"text":"How 811 Works","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"• Call 811 - Contact your local one-call center at least 2-3 business days before you plan to dig.\n• Wait for Marking - Utility operators will mark the approximate location of underground lines with flags or paint.\n• Respect the Marks - Use hand tools or vacuum excavation within 18-24 inches of marked utilities.\n• Dig Safely - Excavate carefully, watching for any unmarked utilities that may have been missed.","style":{"align":"left","textSize":"md","textColor":"default"}}],[{"type":"heading","level":3,"text":"Important Reminders","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"• Call at least 2-3 business days before digging\n• Wait for all utilities to be marked\n• Marks are valid for a limited time\n• Call again if marks are damaged or unclear\n• Use hand tools near marked utilities","style":{"align":"left","textSize":"md","textColor":"default"}}]]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"image","url":"https://usanorth811.org/assets/images/logo.svg","alt":"USA North 811 Logo","caption":"","width":"full","align":"left"},{"type":"heading","level":2,"text":"USA North 811 - Nevada''s Call Center","style":{"align":"center","textSize":"lg","textColor":"default"}},{"type":"text","body":"When you call 811 in Nevada, you''re connected to USA North 811, the one-call center that serves Nevada and Northern California. USA North 811 coordinates with utility operators across the state to ensure all underground utilities are properly marked before you dig.","style":{"align":"center","textSize":"md","textColor":"default"}},{"type":"text","body":"USA North 811 processes dig ticket requests, notifies utility operators of planned excavations, and helps coordinate the marking of underground facilities. They are your direct connection to the damage prevention process in Nevada.","style":{"align":"center","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Visit USA North 811","url":"https://usanorth811.org/","style":{"align":"left"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Utility Marking Color Codes","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Utility locators use standardized colors to mark different types of underground utilities.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Red","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Electric power lines, cables, conduit, and lighting cables","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Yellow","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Gas, oil, steam, petroleum, or gaseous materials","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Orange","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Communication, alarm or signal lines, cables, or conduit","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Blue","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Potable water","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Green","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Sewers and drain lines","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Purple","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Reclaimed water, irrigation, and slurry lines","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"White","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Proposed excavation limits or route","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Pink","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Temporary survey markings","style":{"align":"left","textSize":"md","textColor":"default"}}]},{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"811 Resources & Tools","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"📋","title":"Create a Ticket","body":"Request utility marking for your excavation project through your local one-call center."},{"icon":"📚","title":"Handbooks & Guides","body":"Access best practices guides, excavation handbooks, and damage prevention resources."},{"icon":"❓","title":"Common Questions","body":"Find answers to frequently asked questions about the 811 process and damage prevention."}]}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Nevada Excavation Documents","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Essential documents for safe excavation in Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"📄","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"EPR Codes","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Electronic Positive Response Codes and Descriptions for Nevada.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/NV-EPR-Codes_Update-Announcment.pdf","style":{"align":"left"}},{"type":"text","body":"📖","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Handbook","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Comprehensive guide to safe excavation practices in Nevada (2025 edition).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf","style":{"align":"left"}},{"type":"text","body":"⚖️","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Law (English)","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Nevada excavation law and regulations (2025 edition).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Download PDF","url":"https://usanorth811.org/assets/PDF/Nevada-2025-Law.pdf","style":{"align":"left"}},{"type":"text","body":"⚖️","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":3,"text":"Nevada Excavation Law (Spanish)","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Ley de excavación de Nevada y regulaciones (versión en español).","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"cta_button","label":"Descargar PDF","url":"https://usanorth811.org/assets/PDF/NV-LAW-Spanish.pdf","style":{"align":"left"}}]}]', 1);
INSERT OR REPLACE INTO pages (id, slug, title, section_label, subtitle, body_md, body_json, published)
     VALUES ('00000000-0000-4000-8000-000038b72420', 'contact', 'Contact NRCGA', 'Get in Touch', 'Have questions? Want to get involved? We''d love to hear from you.', NULL, '[{"type":"section","bg":"default","padding":"md","children":[{"type":"heading","level":2,"text":"Contact Information","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"text","body":"Reach out to us through any of the following methods. We typically respond within 1–2 business days.","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Email","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"info@nrcga.org","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"Response Time","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"text","body":"1–2 business days","style":{"align":"left","textSize":"md","textColor":"default"}},{"type":"heading","level":2,"text":"Send us a Message","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"cta_button","label":"Open Contact Form","url":"https://forms.office.com/Pages/ResponsePage.aspx?id=l_bTl4Fr-UGCMvL2nXpxRyBVFANpJf9BgeFLspJ7BSZUQ0VGNFhKQ1BQNlcyNUY5RTVDMTREUlhFVC4u","style":{"align":"left"}}]},{"type":"section","bg":"light","padding":"md","children":[{"type":"heading","level":2,"text":"Other Ways to Connect","style":{"align":"left","textSize":"lg","textColor":"default"}},{"type":"grid","columns":3,"gap":"md","items":[{"icon":"📅","title":"Attend a Meeting","body":"Join us at our regular general member meetings. Check our calendar for upcoming events."},{"icon":"👥","title":"Join a Committee","body":"Get involved with one of our committees focused on education, events, awards, or technical solutions."},{"icon":"📧","title":"Newsletter","body":"Subscribe to our newsletter to stay updated on training sessions, events, and damage prevention news."}]}]}]', 1);